  for (const p of prodResp.values) {
    console.log(`  id=${p.id} number=${p.number} name=${p.name} price=${p.priceExcludingVatCurrency}`);
  }

  // Pick first customer and first two products
  const customer = custResp.values[0];
  if (!customer) throw new Error("No customers in sandbox");
  const products = prodResp.values.slice(0, 2);
