  console.log(`Using products: ${products.map((p: any) => `${p.name}(${p.number})`).join(", ")}`);

  // Now test parallel GETs: customer + product + paymentType all at once
  const t0 = Date.now();
  const [custById, prodByNumber, ptResp] = await Promise.all([
    api("GET", `/customer?organizationNumber=${customer.organizationNumber}&fields=*`),
    api("GET", `/product?number=${products.map((p: any) => p.number).join(",")}&fields=*`),
    api("GET", "/invoice/paymentType?count=1000&fields=*,debitAccount(*),creditAccount(*)"),
  ]);
  const t1 = Date.now();
  console.log(`\nParallel 3 GETs took ${t1 - t0}ms`);

  // Verify all returned correctly
  const resolvedCust = custById.values[0];
  console.log(`Customer resolved: ${resolvedCust?.name} (id=${resolvedCust?.id})`);
  console.log(`Products resolved: ${prodByNumber.values.length} found`);

  const incomingPt = ptResp.values.find((pt: any) => pt.debitAccount?.isBankAccount);
  console.log(`PaymentType: ${incomingPt?.description} (id=${incomingPt?.id})`);

