      { product: { id: prod0.id }, description: prod0.name, count: 1, unitPriceExcludingVatCurrency: 5000 },
      { product: { id: prod1.id }, description: prod1.name, count: 1, unitPriceExcludingVatCurrency: 3000 },
    ],
  });
  const orderId = orderResp.value.id;
  console.log(`Order: ${orderId}`);

  // Step 5: PUT order/:invoice
  const invResp = await api(
    "PUT",
    `/order/${orderId}/:invoice?invoiceDate=${today}&sendToCustomer=false&paymentTypeId=${payType.id}&paidAmount=0.01&paymentTypeIdRestAmount=${payType.id}`
  );
  const inv = invResp.value;
  console.log(`Invoice: ${inv.id}, number=${inv.invoiceNumber}, outstanding=${inv.amountCurrencyOutstanding}`);

  const tf1 = Date.now();
  console.log(`Full flow took ${tf1 - tf0}ms`);
  console.log(`\nDone. 5 API calls (3 parallel + 2 sequential), 0 errors.`);
}

main().catch((e) => { console.error(e); process.exit(1); });

