const BASE = "https://kkpqfuj-amager.tripletex.dev/v2";
const TOKEN = "eyJ0b2tlbklkIjoyMTQ3NjI4NDYxLCJ0b2tlbiI6IjU2NDRjNDljLWU0YzYtNGU2OC05MWU5LWU0MzBhMWRiYTMzYSJ9";
const AUTH = "Basic " + btoa(`0:${TOKEN}`);
const HEADERS = { Authorization: AUTH, "Content-Type": "application/json" };

async function api(method: string, path: string, body?: any) {
  const url = `${BASE}${path}`;
  const opts: RequestInit = { method, headers: HEADERS };
  if (body) opts.body = JSON.stringify(body);
  const res = await fetch(url, opts);
  const json = await res.json();
  console.log(`${method} ${path} → ${res.status}`);
  if (!res.ok) {
    console.error(JSON.stringify(json, null, 2));
    throw new Error(`${method} ${path} failed: ${res.status}`);
  }
  return json;
}

async function main() {
  // First, find what customers and products exist in sandbox
  const [custResp, prodResp] = await Promise.all([
    api("GET", "/customer?count=5&fields=*"),
    api("GET", "/product?count=10&fields=*"),
  ]);

  console.log("\n=== Customers ===");
  for (const c of custResp.values) {
    console.log(`  id=${c.id} name=${c.name} org=${c.organizationNumber}`);
  }

  console.log("\n=== Products ===");
  for (const p of prodResp.values) {
    console.log(`  id=${p.id} number=${p.number} name=${p.name} price=${p.priceExcludingVatCurrency}`);
  }

  // Pick first customer and first two products
  const customer = custResp.values[0];
  if (!customer) throw new Error("No customers in sandbox");
  const products = prodResp.values.slice(0, 2);
  if (products.length < 2) throw new Error("Need at least 2 products");

  console.log(`\nUsing customer: ${customer.name} (id=${customer.id})`);
  console.log(`Using products: ${products.map((p: any) => `${p.name}(${p.number})`).join(", ")}`);

  // Now test parallel GETs: customer + product + paymentType all at once
  const t0 = Date.now();
  const [custById, prodByNumber, ptResp] = await Promise.all([
    api("GET", `/customer?organizationNumber=${customer.organizationNumber}&fields=*`),
    api("GET", `/product?number=${products.map((p: any) => p.number).join(",")}&fields=*`),
    api("GET", "/invoice/paymentType?count=1000&fields=*,debitAccount(*),creditAccount(*)"),
  ]);
  const t1 = Date.now();
  console.log(`\nParallel 3 GETs took ${t1 - t0}ms`);

  // Verify all returned correctly
  const resolvedCust = custById.values[0];
  console.log(`Customer resolved: ${resolvedCust?.name} (id=${resolvedCust?.id})`);
  console.log(`Products resolved: ${prodByNumber.values.length} found`);

  const incomingPt = ptResp.values.find((pt: any) => pt.debitAccount?.isBankAccount);
  console.log(`PaymentType: ${incomingPt?.description} (id=${incomingPt?.id})`);

  // Now do sequential GETs for comparison
  const t2 = Date.now();
  await api("GET", `/customer?organizationNumber=${customer.organizationNumber}&fields=*`);
  await api("GET", `/product?number=${products.map((p: any) => p.number).join(",")}&fields=*`);
  await api("GET", "/invoice/paymentType?count=1000&fields=*,debitAccount(*),creditAccount(*)");
  const t3 = Date.now();
  console.log(`Sequential 3 GETs took ${t3 - t2}ms`);

  console.log(`\nTime saved by parallelization: ${(t3 - t2) - (t1 - t0)}ms`);

  // Now do the full flow with parallelized reads
  console.log("\n=== Full flow with parallel reads ===");
  const tf0 = Date.now();

  // Step 1-3: parallel reads
  const [c, p, pt] = await Promise.all([
    api("GET", `/customer?organizationNumber=${customer.organizationNumber}&fields=*`),
    api("GET", `/product?number=${products.map((pr: any) => pr.number).join(",")}&fields=*`),
    api("GET", "/invoice/paymentType?count=1000&fields=*,debitAccount(*),creditAccount(*)"),
  ]);

  const cust = c.values[0];
  const prod0 = p.values.find((pp: any) => String(pp.number) === String(products[0].number));
  const prod1 = p.values.find((pp: any) => String(pp.number) === String(products[1].number));
  const payType = pt.values.find((ppt: any) => ppt.debitAccount?.isBankAccount);

  // Step 4: POST order
  const today = "2026-03-21";
  const orderResp = await api("POST", "/order", {
    customer: { id: cust.id },
    orderDate: today,
    deliveryDate: today,
    orderLines: [
      { product: { id: prod0.id }, description: prod0.name, count: 1, unitPriceExcludingVatCurrency: 5000 },
      { product: { id: prod1.id }, description: prod1.name, count: 1, unitPriceExcludingVatCurrency: 3000 },
    ],
  });
  const orderId = orderResp.value.id;
  console.log(`Order: ${orderId}`);

  // Step 5: PUT order/:invoice
  const invResp = await api(
    "PUT",
    `/order/${orderId}/:invoice?invoiceDate=${today}&sendToCustomer=false&paymentTypeId=${payType.id}&paidAmount=0.01&paymentTypeIdRestAmount=${payType.id}`
  );
  const inv = invResp.value;
  console.log(`Invoice: ${inv.id}, number=${inv.invoiceNumber}, outstanding=${inv.amountCurrencyOutstanding}`);

  const tf1 = Date.now();
  console.log(`Full flow took ${tf1 - tf0}ms`);
  console.log(`\nDone. 5 API calls (3 parallel + 2 sequential), 0 errors.`);
}

main().catch((e) => { console.error(e); process.exit(1); });
